import React, { useState } from 'react';
import { View, Text, ScrollView, TouchableOpacity, Image } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';

const Container = styled.SafeAreaView`
  flex: 1;
  background-color: ${colors.white};
`;

const Header = styled.View`
  height: 60px;
  flex-direction: row;
  align-items: center;
  padding-horizontal: ${spacing.md}px;
  border-bottom-width: 1px;
  border-bottom-color: ${colors.border};
`;

const HeaderTitle = styled.Text`
  flex: 1;
  font-size: 18px;
  font-weight: 600;
  text-align: center;
  margin-right: 40px; /* Offset para centralizar por causa do botão voltar */
`;

const CategoryList = styled.ScrollView`
  flex: 1;
  padding: ${spacing.md}px;
`;

const CategoryCard = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding: ${spacing.md}px;
  border-radius: ${borderRadius.lg}px;
  border-width: 2px;
  border-color: ${props => props.selected ? colors.primary : colors.border};
  background-color: ${props => props.selected ? colors.surface : colors.white};
  margin-bottom: ${spacing.md}px;
`;

const CategoryImage = styled.View`
  width: 80px;
  height: 50px;
  background-color: #eee;
  border-radius: ${borderRadius.sm}px;
  justify-content: center;
  align-items: center;
`;

const CategoryInfo = styled.View`
  flex: 1;
  margin-left: ${spacing.md}px;
`;

const CategoryName = styled.Text`
  font-size: 18px;
  font-weight: bold;
  color: ${colors.text};
`;

const CategoryPrice = styled.Text`
  font-size: 16px;
  font-weight: 500;
  color: ${colors.text};
  margin-top: 2px;
`;

const SelectionText = styled.Text`
  font-size: 14px;
  color: ${colors.textSecondary};
  margin-top: 4px;
`;

const SectionTitle = styled.Text`
  font-size: 16px;
  font-weight: bold;
  margin-vertical: ${spacing.sm}px;
  padding-horizontal: ${spacing.md}px;
  color: ${colors.text};
`;

const PaymentContainer = styled.View`
  padding: ${spacing.md}px;
`;

const PaymentOption = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding-vertical: ${spacing.sm}px;
`;

const RadioCircle = styled.View`
  height: 20px;
  width: 20px;
  border-radius: 10px;
  border-width: 2px;
  border-color: ${props => props.selected ? colors.primary : colors.textSecondary};
  align-items: center;
  justify-content: center;
  margin-right: ${spacing.sm}px;
`;

const SelectedDot = styled.View`
  height: 10px;
  width: 10px;
  border-radius: 5px;
  background-color: ${colors.primary};
`;

const PaymentText = styled.Text`
  font-size: 16px;
  color: ${colors.text};
`;

const Footer = styled.View`
  padding: ${spacing.md}px;
  border-top-width: 1px;
  border-top-color: ${colors.border};
`;

const ConfirmButton = styled.TouchableOpacity`
  background-color: ${colors.black};
  height: 55px;
  border-radius: ${borderRadius.md}px;
  justify-content: center;
  align-items: center;
`;

const ConfirmButtonText = styled.Text`
  color: ${colors.white};
  font-size: 18px;
  font-weight: bold;
`;

const SelectionScreen = () => {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('dinheiro');
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  React.useEffect(() => {
    loadCategories();
  }, []);

  const loadCategories = async () => {
    try {
      const response = await api.passenger.getCategories(1); // Ex: cidade_id = 1
      if (response.data && Array.isArray(response.data)) {
        setCategories(response.data);
        if (response.data.length > 0) setSelectedCategory(response.data[0].id);
      } else if (response.data === 'no') {
          setCategories([]);
      }
    } catch (error) {
      console.error('Erro ao carregar categorias:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = async () => {
      // Aqui chamaria api.passenger.requestRide(...)
      alert('Solicitando viagem...');
  };

  if (loading) {
      return (
          <Container style={{ justifyContent: 'center', alignItems: 'center' }}>
              <ActivityIndicator size="large" color={colors.primary} />
          </Container>
      );
  }

  return (
    <Container>
      <Header>
        <TouchableOpacity>
          <Icon name="arrow-back" size={28} color={colors.secondary} />
        </TouchableOpacity>
        <HeaderTitle>Escolha o tipo de viagem</HeaderTitle>
      </Header>

      <CategoryList showsVerticalScrollIndicator={false}>
        {categories.map((cat) => (
          <CategoryCard 
            key={cat.id} 
            selected={selectedCategory === cat.id}
            onPress={() => setSelectedCategory(cat.id)}
          >
            <CategoryImage>
              <Icon name="directions-car" size={40} color={colors.secondary} />
            </CategoryImage>
            <CategoryInfo>
              <CategoryName>{cat.nome}  {cat.tx_base ? `R$ ${cat.tx_base}` : cat.price}</CategoryName>
              <SelectionText>{cat.descricao || 'Clique para selecionar'}</SelectionText>
            </CategoryInfo>
            {selectedCategory === cat.id && (
              <Icon name="check-circle" size={24} color={colors.primary} />
            )}
          </CategoryCard>
        ))}

        <SectionTitle>Forma de Pagamento:</SectionTitle>
        <PaymentContainer>
          {[
            { id: 'dinheiro', label: 'Dinheiro', icon: 'payments' },
            { id: 'carteira', label: 'Carteira Crédito', icon: 'account-balance-wallet' },
            { id: 'maquina', label: 'Cartão Máquina', icon: 'credit-card' },
          ].map((item) => (
            <PaymentOption key={item.id} onPress={() => setPaymentMethod(item.id)}>
              <RadioCircle selected={paymentMethod === item.id}>
                {paymentMethod === item.id && <SelectedDot />}
              </RadioCircle>
              <PaymentText>{item.label}</PaymentText>
            </PaymentOption>
          ))}
        </PaymentContainer>
      </CategoryList>

      <Footer>
        <ConfirmButton activeOpacity={0.8} onPress={handleConfirm}>
          <ConfirmButtonText>
            Confirmar {categories.find(c => c.id === selectedCategory)?.nome}
          </ConfirmButtonText>
        </ConfirmButton>
      </Footer>
    </Container>
  );
};

export default SelectionScreen;
